/* Integrate player motion, resolve contacts, and measure the resulting movement. */
void HeroMovePipeline(void) {
    Vec4 previous;
    Vec4 work;
    Vec4 plane;
    Hero *contact_player;
    Hero *motion_player;
    Hero *cap_player;
    float *position = (float *)&g_hero.motion.pos;
    Hero *player;
    float *vertical;
    float *horizontal;
    float *extra_step;
    float *velocity;
    float *new_position;
    float *contact;
    float *external;
    float magnitude;

    qcopy(previous.f, position);
    player = (Hero *)((char *)position - 0x80);
    update_hero_attachment(player->ledge_moby, (char *)position + 0x70, (char *)position + 0x10);
    if (player->state.current == HERO_STATE_RISE_THEN_FALL_WITH_AIRBORNE_HIT_QUERY ||
        player->state.current == HERO_STATE_WRENCH_SLAM) {
        float limit;

        if (!player->collision_off_frames) {
            float length;

            position = (float *)((char *)position + 0x60);
            length = gravity_length_xy(position);
            limit = player->capsule_radius - 0.02f;
            if (limit < length)
                vec_scale_to_length(position, position, limit);
        }
        position = (float *)&g_hero.motion.velocity;
        magnitude = gravity_z(position);
        limit = -*(float *)((char *)position + 0x1FC);
        if (magnitude < limit) {
            if (limit > 0.0f)
                limit = 0.0f;
            gravity_set_z(position, position, limit);
        }
    } else {
        if (!player->collision_off_frames) {
            float length;
            float limit;

            position = (float *)((char *)position + 0x60);
            length = FastVecLength(position);
            limit = player->capsule_radius - 0.02f;
            if (limit < length)
                vec_scale_to_length(position, position, limit);
        }
    }
    position = (float *)&g_hero.motion.pos;
    FastVecAdd(position, position, (char *)position + 0x60);
    extra_step = (float *)((char *)position + 0x8A0);
    FastVecAdd(position, position, extra_step);
    clear_u64_value(extra_step);
    contact_player = (Hero *)((char *)position - 0x80);
    contact_player->wall_hit = 0;
    contact_player->coll_hit_moby = 0;
    if (FastVecLength((char *)position + 0x70) <= 0.0001f) {
        resolve_hero_collisions_with_history();
        HeroGroundProbe();
        FastVecSub((char *)position + 0x80, position, previous.f);
        correct_hero_ground_penetration();
    } else {
        HeroGroundProbe();
    }
    position = (float *)&g_hero.motion.resolved_velocity;
    new_position = (float *)((char *)position - 0x90);
    horizontal = (float *)((char *)position + 0x20);
    FastVecSub(position, new_position, previous.f);
    qcopy(horizontal, position);
    vertical = (float *)((char *)position + 0x10);
    qcopy(vertical, position);
    velocity = (float *)((char *)position - 0x30);
    vec_scale_to_length(position, position, 1.0f);
    magnitude = FastVecDot(position, velocity);
    if (magnitude < 0.0f)
        magnitude = 0.0f;
    vec_scale_to_length(position, velocity, magnitude);
    qcopy(work.f, velocity);
    gravity_flatten(work.f, work.f);
    gravity_flatten(horizontal, horizontal);
    vec_scale_to_length(horizontal, horizontal, 1.0f);
    magnitude = FastVecDot(horizontal, work.f);
    if (magnitude < 0.0f)
        magnitude = 0.0f;
    vec_scale_to_length(horizontal, work.f, magnitude);
    qcopy(plane.f, velocity);
    set_gravity_relative_vector_length_xy(plane.f, plane.f, 0.0f);
    set_gravity_relative_vector_length_xy(vertical, vertical, 0.0f);
    vec_scale_to_length(vertical, vertical, 1.0f);
    magnitude = FastVecDot(vertical, plane.f);
    if (magnitude < 0.0f)
        magnitude = 0.0f;
    vec_scale_to_length(vertical, plane.f, magnitude);
    motion_player = (Hero *)((char *)position - 0x110);
    motion_player->motion.speed_xy = FastVecLength(position);
    magnitude = vector_length_xy(position);
    work.q = *(Q_2343F8 *)position;
    motion_player->motion.flat_speed = magnitude;
    motion_player->motion.forward_speed = forward_component(work.f);
    if (motion_player->motion.forward_speed < 0.0f)
        motion_player->motion.forward_speed = 0.0f;
    qcopy(work.f, new_position);
    contact = (float *)((char *)position - 0x20);
    external = (float *)((char *)position - 0x10);
    if (FastVecLength(contact) > 0.0001f) {
        float saved;

        FastVecAdd(new_position, new_position, contact);
        saved = motion_player->motion.platform_delta.f[3];
        clear_u64_value(contact);
        motion_player->motion.platform_delta.f[3] = saved;
        resolve_hero_collisions_with_history();
        HeroGroundProbe();
        FastVecSub(external, new_position, previous.f);
        correct_hero_ground_penetration();
    }
    FastVecSub((char *)position + 0x30, new_position, work.f);
    motion_player->motion.platform_carry.f[3] = motion_player->motion.platform_delta.f[3];
    motion_player->motion.platform_delta.f[3] = 0.0f;
    FastVecSub(external, new_position, previous.f);
    motion_player->motion.move_slope = 0.0f;
    if (motion_player->motion.flat_speed > 0.004f) {
        motion_player->motion.move_slope = motion_player->motion.displacement.f[2] / motion_player->motion.flat_speed;
        if (motion_player->motion.move_slope > 0.5f)
            motion_player->motion.move_slope = 0.5f;
        else if (motion_player->motion.move_slope < -0.5f)
            motion_player->motion.move_slope = -0.5f;
    }
    cap_player = &g_hero;
    magnitude = g_frame_time * 52.0f;
    if (magnitude < cap_player->motion.speed_xy) {
        FastVecScale(cap_player->motion.displacement.f, cap_player->motion.displacement.f,
                     magnitude / cap_player->motion.speed_xy);
        cap_player->motion.speed_xy = g_frame_time * 52.0f;
    }
}
